const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const bin = item.binary || {};
  const json = item.json || {};

  const sender =
    json.from?.text ||
    json.from?.value?.[0]?.address ||
    json.headers?.from ||
    json.From ||
    '';

  for (const [key, fileObj] of Object.entries(bin)) {
    if (!fileObj || !fileObj.data) continue;

    const mime = (fileObj.mimeType || '').toLowerCase();
    const ext = (fileObj.fileExtension || '').toLowerCase();
    const name = fileObj.fileName || `${key}.${ext || 'bin'}`;

    const isPdf = mime.includes('pdf') || ext === 'pdf' || name.toLowerCase().endsWith('.pdf');
    const isImage = mime.startsWith('image/') || ['jpg', 'jpeg', 'png', 'webp', 'gif', 'bmp', 'tif', 'tiff'].includes(ext);

    if (!isPdf && !isImage) continue;

    // Skip tiny tracking pixels / social signature icons (< 4KB) safely using real binary buffer
    if (isImage) {
      try {
        const buf = await this.helpers.getBinaryDataBuffer(i, key);
        if (buf && buf.length < 4000) continue;
      } catch {}
    }

    out.push({
      json: {
        source: 'gmail',
        emailMessageId: json.id || '',
        subject: json.subject || json.Subject || '',
        sender,
        receivedDate: json.date || new Date().toISOString(),
        textContext: (json.text || json.snippet || '').slice(0, 1500),
        fileName: name,
        mimeType: fileObj.mimeType || (isPdf ? 'application/pdf' : 'image/jpeg'),
        fileExtension: ext || (isPdf ? 'pdf' : 'jpg'),
      },
      binary: { data: fileObj },
      pairedItem: { item: i },
    });
  }
}

return out;

const staticData = $getWorkflowStaticData('global');
const offset = staticData.lastTelegramUpdateId ? Number(staticData.lastTelegramUpdateId) + 1 : 0;
return [{ json: { offset } }];

const staticData = $getWorkflowStaticData('global');
const resp = $input.first()?.json || {};
const updates = Array.isArray(resp.result) ? resp.result : [];

let maxUpdateId = staticData.lastTelegramUpdateId || 0;
const out = [];

for (const upd of updates) {
  if (typeof upd.update_id === 'number' && upd.update_id > maxUpdateId) {
    maxUpdateId = upd.update_id;
  }

  const msg = upd.message || upd.channel_post;
  if (!msg) continue;

  const chatId = String(msg.chat?.id ?? '');
  const sender =
    [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') ||
    msg.from?.username ||
    msg.chat?.title ||
    'Telegram User';
  const receivedDate = msg.date ? new Date(msg.date * 1000).toISOString() : new Date().toISOString();
  const textContext = msg.caption || msg.text || '';

  if (msg.document && msg.document.file_id) {
    const doc = msg.document;
    const mime = (doc.mime_type || '').toLowerCase();
    const fname = doc.file_name || `telegram_${upd.update_id}.pdf`;
    const isPdf = mime.includes('pdf') || fname.toLowerCase().endsWith('.pdf');
    const isImg = mime.startsWith('image/') || /\.(jpg|jpeg|png|webp|gif)$/i.test(fname);
    if (!isPdf && !isImg) continue;

    out.push({
      json: {
        source: 'telegram',
        emailMessageId: '',
        telegramUpdateId: upd.update_id,
        telegramChatId: chatId,
        subject: `טלגרם DOSI - ${sender}`,
        sender,
        receivedDate,
        textContext,
        fileId: doc.file_id,
        fileName: fname,
        mimeType: doc.mime_type || (isPdf ? 'application/pdf' : 'image/jpeg'),
        fileExtension: fname.includes('.') ? fname.split('.').pop().toLowerCase() : (isPdf ? 'pdf' : 'jpg'),
      },
    });
  } else if (Array.isArray(msg.photo) && msg.photo.length > 0) {
    const largest = msg.photo[msg.photo.length - 1];
    out.push({
      json: {
        source: 'telegram',
        emailMessageId: '',
        telegramUpdateId: upd.update_id,
        telegramChatId: chatId,
        subject: `טלגרם DOSI - ${sender}`,
        sender,
        receivedDate,
        textContext,
        fileId: largest.file_id,
        fileName: `receipt_${upd.update_id}.jpg`,
        mimeType: 'image/jpeg',
        fileExtension: 'jpg',
      },
    });
  }
}

if (maxUpdateId > (staticData.lastTelegramUpdateId || 0)) {
  staticData.lastTelegramUpdateId = maxUpdateId;
}

return out;

const items = $input.all();
const validCount = items.filter((i) => i.json?.output?.is_valid_invoice === true).length;
if (validCount === 0 && items.length > 0) {
  return [{ json: { triggerDashboard: true } }];
}
return [];

const airtableItems = $input.all().filter((i) => i.json && i.json.id);
const runItems = $('Restore Binary After Agent').all();

let duplicatesDeletedMcp = 0;
try {
  const dedupeItems = $('Deduplicate Airtable via MCP').all();
  for (const d of dedupeItems) {
    const raw = String(d.json?.output || '');
    const m = raw.match(/"duplicates_deleted"\s*:\s*(\d+)/);
    if (m) duplicatesDeletedMcp += Number(m[1]) || 0;
  }
} catch {}

let newRowsWrittenCount = 0;
try {
  const prep = $('Prepare Airtable Rows').all();
  newRowsWrittenCount = prep.filter((r) => r.json?._hasRows === true).length;
} catch {}

const totalScanned = runItems.length;
const validInvoices = runItems.filter((i) => i.json?.output?.is_valid_invoice === true);
const rejected = runItems.filter((i) => i.json?.output?.is_valid_invoice !== true);

const gmailCount = runItems.filter((i) => i.json?.source === 'gmail').length;
const telegramCount = runItems.filter((i) => i.json?.source === 'telegram').length;
const runTotalILS = validInvoices.reduce((sum, i) => sum + (Number(i.json?.output?.total_ils) || 0), 0);

// Count Airtable totals without double-counting line items + "סה"כ" summary rows
const summaryRows = airtableItems.filter((r) => {
  const f = r.json?.fields || r.json || {};
  return String(f['פריטים \\ מוצרים'] || '').startsWith('סה"כ');
});
const totalInvoicesInTable = summaryRows.length > 0 ? summaryRows.length : airtableItems.length;
const totalAirtableILS = (summaryRows.length > 0 ? summaryRows : airtableItems).reduce((sum, r) => {
  const f = r.json?.fields || r.json || {};
  const val = Number(f['סכום כולל'] ?? 0);
  return sum + (Number.isFinite(val) ? val : 0);
}, 0);

const esc = (s) =>
  String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const fmtNum = (n) => Number(n || 0).toLocaleString('he-IL', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const rowsHtml = runItems
  .map((i) => {
    const o = i.json?.output || {};
    const srcLabel = i.json?.source === 'telegram' ? 'טלגרם (DOSI)' : 'Gmail';
    const lineCount = Array.isArray(o.line_items) ? o.line_items.length : 0;
    const badge = o.is_valid_invoice
      ? `<span style="background:#DCFCE7;color:#166534;padding:3px 8px;border-radius:12px;font-size:12px;font-weight:600;">תקין (${lineCount} פעולות + סה"כ)</span>`
      : `<span style="background:#FEE2E2;color:#991B1B;padding:3px 8px;border-radius:12px;font-size:12px;font-weight:600;">סונן (${esc(o.document_type || 'לא חשבונית')})</span>`;
    const drivePath = o.is_valid_invoice
      ? `${esc(o.topic)} / ${esc(o.year)} / ${esc(o.month)} / ${esc(o.drive_file_name)}`
      : '—';

    return `
      <tr style="border-bottom:1px solid #E5E7EB;">
        <td style="padding:10px 8px;font-weight:600;color:#111827;">${esc(o.title_he || i.json?.fileName || 'ללא כותרת')}</td>
        <td style="padding:10px 8px;color:#374151;">${esc(o.client_or_vendor_name || '—')}</td>
        <td style="padding:10px 8px;color:#374151;">${esc(o.description_he || '—')}</td>
        <td style="padding:10px 8px;color:#374151;">${esc(o.invoice_date || '—')}</td>
        <td style="padding:10px 8px;color:#374151;">${esc(srcLabel)}</td>
        <td style="padding:10px 8px;color:#111827;font-weight:600;">₪${fmtNum(o.total_ils)}</td>
        <td style="padding:10px 8px;">${badge}</td>
        <td style="padding:10px 8px;color:#4B5563;font-size:12px;">${drivePath}</td>
      </tr>`;
  })
  .join('');

const runTime = DateTime.now().setZone('Asia/Jerusalem').toFormat('dd/MM/yyyy HH:mm');

const htmlDashboard = `
<!DOCTYPE html>
<html dir="rtl" lang="he">
<head><meta charset="utf-8"></head>
<body style="margin:0;padding:24px;background-color:#F3F4F6;font-family:Arial,Helvetica,sans-serif;direction:rtl;text-align:right;color:#1F2937;">
  <div style="max-width:920px;margin:0 auto;background:#FFFFFF;border-radius:14px;overflow:hidden;box-shadow:0 4px 18px rgba(0,0,0,0.07);border:1px solid #E5E7EB;">
    <div style="background:linear-gradient(135deg,#0F172A 0%,#1E3A8A 100%);padding:26px 28px;color:#FFFFFF;">
      <h1 style="margin:0;font-size:22px;font-weight:700;">📊 דשבורד חילוץ וניהול חשבוניות</h1>
      <p style="margin:6px 0 0;font-size:13px;color:#CBD5E1;">סיכום סריקה אוטומטית (Gmail + טלגרם DOSI) | מועד ריצה: ${esc(runTime)}</p>
    </div>

    <div style="padding:24px 28px;">
      <div style="display:flex;flex-wrap:wrap;gap:12px;margin-bottom:22px;">
        <div style="flex:1;min-width:150px;background:#EFF6FF;border:1px solid #BFDBFE;border-radius:10px;padding:14px;">
          <div style="font-size:12px;color:#1E40AF;font-weight:600;">מסמכים שנסרקו</div>
          <div style="font-size:26px;font-weight:700;color:#1E3A8A;margin-top:4px;">${totalScanned}</div>
          <div style="font-size:11px;color:#3B82F6;margin-top:2px;">Gmail: ${gmailCount} | טלגרם: ${telegramCount}</div>
        </div>
        <div style="flex:1;min-width:150px;background:#F0FDF4;border:1px solid #BBF7D0;border-radius:10px;padding:14px;">
          <div style="font-size:12px;color:#166534;font-weight:600;">חשבוניות תקינות</div>
          <div style="font-size:26px;font-weight:700;color:#14532D;margin-top:4px;">${validInvoices.length}</div>
          <div style="font-size:11px;color:#15803D;margin-top:2px;">שורות חדשות שנכתבו: ${newRowsWrittenCount} | ₪${fmtNum(runTotalILS)}</div>
        </div>
        <div style="flex:1;min-width:150px;background:#FEF3C7;border:1px solid #FDE68A;border-radius:10px;padding:14px;">
          <div style="font-size:12px;color:#92400E;font-weight:600;">כפיליות שנמחקו ב-MCP</div>
          <div style="font-size:26px;font-weight:700;color:#78350F;margin-top:4px;">${duplicatesDeletedMcp}</div>
          <div style="font-size:11px;color:#B45309;margin-top:2px;">נבדק אוטומטית ב-Airtable MCP</div>
        </div>
        <div style="flex:1;min-width:150px;background:#FEF2F2;border:1px solid #FECACA;border-radius:10px;padding:14px;">
          <div style="font-size:12px;color:#991B1B;font-weight:600;">מסמכים שסוננו</div>
          <div style="font-size:26px;font-weight:700;color:#7F1D1D;margin-top:4px;">${rejected.length}</div>
          <div style="font-size:11px;color:#B91C1C;margin-top:2px;">זיכוי / הצעת מחיר / אחר</div>
        </div>
      </div>

      <div style="background:#F8FAFC;border:1px solid #E2E8F0;border-radius:10px;padding:14px 18px;margin-bottom:22px;">
        <div style="font-size:14px;font-weight:700;color:#0F172A;margin-bottom:4px;">🗄️ מצב מצטבר בטבלת "הנהלת חשבונות" (Airtable)</div>
        <div style="font-size:13px;color:#475569;">
          סה"כ חשבוניות בטבלה: <strong>${totalInvoicesInTable}</strong> (סה"כ ${airtableItems.length} שורות כולל פירוט פעולות) &nbsp;|&nbsp;
          סה"כ סכום מצטבר: <strong>₪${fmtNum(totalAirtableILS)}</strong>
        </div>
      </div>

      <h2 style="font-size:16px;margin:0 0 10px;color:#111827;">פירוט מסמכים מהרצה זו</h2>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:13px;text-align:right;">
          <thead>
            <tr style="background:#F1F5F9;color:#334155;border-bottom:2px solid #CBD5E1;">
              <th style="padding:10px 8px;">כותרת (נושא השירות)</th>
              <th style="padding:10px 8px;">חברה</th>
              <th style="padding:10px 8px;">תיאור הצורך</th>
              <th style="padding:10px 8px;">תאריך</th>
              <th style="padding:10px 8px;">מקור</th>
              <th style="padding:10px 8px;">סכום (₪)</th>
              <th style="padding:10px 8px;">סטטוס</th>
              <th style="padding:10px 8px;">מיקום ב-Google Drive</th>
            </tr>
          </thead>
          <tbody>
            ${rowsHtml || '<tr><td colspan="8" style="padding:14px;text-align:center;color:#6B7280;">לא נמצאו פריטים</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    subject: `📊 דשבורד חשבוניות: ${validInvoices.length} תקינות | ${totalScanned} נסרקו (${runTime})`,
    htmlDashboard,
    totalScanned,
    validCount: validInvoices.length,
    rejectedCount: rejected.length,
    totalInvoicesInTable,
  },
}];

const items = $input.all();
return items.map((item, idx) => {
  const raw = item.json?.output ?? item.json?.text ?? '';
  let parsed = null;

  if (raw && typeof raw === 'object') {
    parsed = raw;
  } else if (typeof raw === 'string') {
    const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    try {
      parsed = JSON.parse(cleaned);
    } catch {
      const start = cleaned.indexOf('{');
      const end = cleaned.lastIndexOf('}');
      if (start !== -1 && end > start) {
        try {
          parsed = JSON.parse(cleaned.slice(start, end + 1));
        } catch {
          parsed = null;
        }
      }
    }
  }

  if (!parsed || typeof parsed !== 'object') {
    parsed = {
      is_valid_invoice: false,
      document_type: 'שגיאת פענוח',
      rejection_reason: 'לא ניתן היה לחלץ מבנה תקין מתשובת הסוכן',
      title_he: 'שגיאה בפענוח מסמך',
      description_he: 'שגיאה בפענוח המסמך',
      invoice_date: '',
      client_or_vendor_name: '',
      company_id_hp: '',
      items_he: '',
      line_items: [],
      original_currency: 'ILS',
      original_total: 0,
      exchange_rate_used: 1,
      total_ils: 0,
      vat_ils: 0,
      topic: 'כללי',
      year: DateTime.now().toFormat('yyyy'),
      month: DateTime.now().toFormat('MM'),
      day: DateTime.now().toFormat('dd'),
      drive_file_name: 'לא רלוונטי',
    };
  }

  // Enforce max 5 words in description_he
  if (typeof parsed.description_he === 'string') {
    const words = parsed.description_he.trim().split(/\s+/).filter(Boolean);
    if (words.length > 5) {
      parsed.description_he = words.slice(0, 5).join(' ');
    }
  }

  // Ensure line_items array exists
  if (!Array.isArray(parsed.line_items) || parsed.line_items.length === 0) {
    if (parsed.is_valid_invoice) {
      parsed.line_items = [{
        item_title: parsed.items_he || parsed.title_he || 'שירות',
        total_ils: Number(parsed.total_ils) || 0,
        vat_ils: Number(parsed.vat_ils) || 0,
      }];
    } else {
      parsed.line_items = [];
    }
  }

  return {
    json: { output: parsed },
    pairedItem: { item: idx },
  };
});

const existingItems = $input.all().filter((i) => i.json && i.json.id);
const validItems = $('Is Valid Invoice or Receipt?').all();

const norm = (s) => String(s ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
const makeKey = (title, company, date, total) =>
  `${norm(title)}|${norm(company)}|${norm(date)}|${Math.round((Number(total) || 0) * 100)}`;
const makeCompanyKey = (company, date, total) =>
  `${norm(company)}|${norm(date)}|${Math.round((Number(total) || 0) * 100)}`;

const existingKeys = new Set();
const existingCompanyKeys = new Set();

for (const rec of existingItems) {
  const f = rec.json?.fields || rec.json || {};
  const t = f['כותרת'] || '';
  const c = f['שם לקוח'] || '';
  const d = f['תאריך הפקת חשבונית'] || '';
  const tot = f['סכום כולל'] ?? 0;
  const itemCol = String(f['פריטים \\ מוצרים'] || '');

  if (itemCol.startsWith('סה"כ') || t) {
    existingKeys.add(makeKey(t, c, d, tot));
    if (c && d) existingCompanyKeys.add(makeCompanyKey(c, d, tot));
  }
}

const rowsOut = [];

for (const item of validItems) {
  const o = item.json?.output || {};
  if (!o.is_valid_invoice) continue;

  const title = (o.title_he || 'שירות כללי').trim();
  const company = (o.client_or_vendor_name || '').trim();
  const date = (o.invoice_date || '').trim();
  const total = Number(o.total_ils) || 0;
  const vat = Number(o.vat_ils) || 0;
  const hp = (o.company_id_hp || '').trim();
  const desc = (o.description_he || '').trim();

  const k1 = makeKey(title, company, date, total);
  const k2 = makeCompanyKey(company, date, total);

  if (existingKeys.has(k1) || (company && date && existingCompanyKeys.has(k2))) {
    continue;
  }

  existingKeys.add(k1);
  if (company && date) existingCompanyKeys.add(k2);

  const lineItems = Array.isArray(o.line_items) && o.line_items.length > 0
    ? o.line_items
    : [{ item_title: o.items_he || title, total_ils: total, vat_ils: vat }];

  for (const li of lineItems) {
    const subTitle = (li.item_title || title).trim();
    rowsOut.push({
      json: {
        _hasRows: true,
        _rowKind: 'item',
        'כותרת': `${title} — ${subTitle}`,
        'תיאור': desc,
        'תאריך הפקת חשבונית': date,
        'שם לקוח': company,
        'ח.פ לקוח': hp,
        'פריטים \\ מוצרים': subTitle,
        'סכום כולל': Math.round((Number(li.total_ils) || 0) * 100) / 100,
        'מע"מ': Math.round((Number(li.vat_ils) || 0) * 100) / 100,
      },
    });
  }

  rowsOut.push({
    json: {
      _hasRows: true,
      _rowKind: 'total',
      'כותרת': title,
      'תיאור': desc,
      'תאריך הפקת חשבונית': date,
      'שם לקוח': company,
      'ח.פ לקוח': hp,
      'פריטים \\ מוצרים': `סה"כ — ${title} (${lineItems.length} פעולות)`,
      'סכום כולל': Math.round(total * 100) / 100,
      'מע"מ': Math.round(vat * 100) / 100,
    },
  });
}

if (rowsOut.length === 0) {
  return [{ json: { _hasRows: false } }];
}

return rowsOut;
